
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_blyp_ea_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_blyp_ea", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.207649666513819e+00, -4.125457049486033e+00, -4.010333341583601e+00, -3.850955670786837e+00, -3.633976867324175e+00, -3.345564750131043e+00, -2.974994507474860e+00, -2.520889163085028e+00, -1.998680107956829e+00, -1.441893496691712e+00, -8.973500052829556e-01, -5.723841548261741e-01, -4.798735693048939e-01, -3.696843617360906e-01, -2.210219243889612e-01, -7.937215527992869e-02, -5.852489722975919e-03, -1.196425555859353e-03, -7.611169405983321e-05, -1.751856069826107e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


